import type { JSX } from "react";

/**
 * Refração de borda "Liquid Glass" de verdade (feDisplacementMap, não só blur) pro cartão
 * principal da reserva externa (um por vez na tela, ver .cartaoVidro/.fechadoCartao em
 * experiencia.module.css) — mesma técnica de src/app/reservas/VidroLiquido.tsx.
 *
 * bezel/scale calibrados pela referência de física da skill liquid-glass: "o scale deve ser
 * igual ao bezel_width, em pixels" (pro modo SDF) — antes o scale (-17) estava bem menor que o
 * bezel (30), o que deixava a refração fraca demais mesmo com uma faixa de borda larga. Bezel
 * também aumentado (30 -> 36) a pedido do Victor, pra a borda de vidro ficar mais grossa/visível.
 */
export function DefinicoesDoVidroLiquidoExterno(): JSX.Element {
  return (
    <svg width="0" height="0" style={{ position: "absolute" }} aria-hidden="true">
      <defs>
        <filter id="vidro-cartao-externo" colorInterpolationFilters="sRGB" x="0%" y="0%" width="100%" height="100%">
          <feImage result="dispCartao" x="0" y="0" width="400" height="340" preserveAspectRatio="none" href="data:image/png;base64," />
          <feDisplacementMap in="SourceGraphic" in2="dispCartao" scale="-36" xChannelSelector="R" yChannelSelector="G" />
        </filter>
      </defs>
    </svg>
  );
}
